const tok = (document.cookie.match(/fssessionid=([^;]+)/)||[])[1];
const H={headers:{Accept:'application/x-fs-v1+json', ...(tok?{Authorization:'Bearer '+tok}:{})}, credentials:'include'};
let out=[]; let pid='L286-83H';
for (let round=0; round<6 && pid; round++){
  const r = await fetch(`/platform/tree/ancestry?person=${pid}&generations=8&personDetails=true`, H);
  if(r.status!==200){out.push('status '+r.status); break;}
  const j=await r.json();
  const ps=j.persons.sort((a,b)=>a.display.ascendancyNumber-b.display.ascendancyNumber);
  // keep father line only: ascendancy numbers powers of 2
  const line=ps.filter(p=>{const n=+p.display.ascendancyNumber; return n>0 && (n&(n-1))===0;});
  for(const p of line) if(p.id!==pid || round===0) out.push([p.id,p.display.name,p.display.lifespan,(p.names||[]).map(n=>n.nameForms.map(f=>f.fullText).join(' / ')).join(' | ')].join('  '));
  const top=line[line.length-1]; pid = (top && top.id!==pid && line.length>1) ? top.id : null;
  // also report non-father-line extras at top round
  out.push('-- others in this window: '+ps.filter(p=>!line.includes(p)).map(p=>p.display.ascendancyNumber+':'+p.display.name).join(', '));
}
out.join('\n')

