const tok = (document.cookie.match(/fssessionid=([^;]+)/)||[])[1];
const H={headers:{Accept:'application/x-fs-v1+json', ...(tok?{Authorization:'Bearer '+tok}:{})}, credentials:'include'};
const ids=['L286-81J','L286-827','L286-8NC','L286-88M','L286-83H','L286-ZB8','L286-ZRX','L286-ZPN','L286-Z2L','L286-ZKM','L286-ZJC','L286-Z87','L286-ZQG','LHP7-98D'];
let out=[];
for(const id of ids){
  const s=await fetch(`/platform/tree/persons/${id}/sources`,H); let n='?'; let titles='';
  if(s.status===200){const j=await s.json(); n=(j.sourceDescriptions||[]).length; titles=(j.sourceDescriptions||[]).map(d=>(d.titles||[]).map(t=>t.value).join('')).join(' ;; ');} else if(s.status===204) n=0; else n='status '+s.status;
  const pr=await fetch(`/platform/tree/persons/${id}/parents`,H); let par='';
  if(pr.status===200){const j=await pr.json(); par=(j.persons||[]).filter(p=>p.id!==id).map(p=>p.id+' '+p.display.name).join(', ');}
  const cr=await fetch(`/platform/tree/persons/${id}/change-summary`,H);
  out.push(`${id} | sources=${n} ${titles} | parents: ${par||'none'}`);
}
out.join('\n')

